#!/usr/bin/env dotnet
// friday13.cs — Find earliest Friday the 13th and count them in a 400-year cycle

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, keep searching
if (earliest is null)
{
    date = new DateTime(2, 1, 13);
    while (true)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = date;
            break;
        }
        date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th (proleptic Gregorian): {earliest:yyyy-MM-dd}");
Console.WriteLine($"  Day of week check: {earliest!.Value.DayOfWeek}");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
var cycleStart = new DateTime(1, 1, 13);
var cycleEnd = new DateTime(401, 1, 1);

date = cycleStart;
while (date < cycleEnd)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
        count++;
    date = date.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();

// Bonus: distribution by month
var byMonth = new int[12];
date = cycleStart;
while (date < cycleEnd)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
        byMonth[date.Month - 1]++;
    date = date.AddMonths(1);
}

Console.WriteLine("Distribution by month (400-year cycle):");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateTime(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");

